mapper.sql:
WHERE p.status='VISIBLE' AND p.category=#{category} AND p.medication_id=#{medicationId}
AND (INSTR(LOWER(p.title),LOWER(#{keyword}))>0 OR INSTR(LOWER(p.medication_name),LOWER(#{keyword}))>0 OR DBMS_LOB.INSTR(LOWER(p.content),LOWER(#{keyword}))>0
OR EXISTS (SELECT 1 FROM medications search_med WHERE search_med.medication_id=p.medication_id AND (INSTR(LOWER(search_med.item_name),LOWER(#{keyword}))>0 OR INSTR(LOWER(search_med.material_name),LOWER(#{keyword}))>0)))
